# Starts, stops and queries the llama.cpp server (llama-server in router mode).
# Needs lib\Config.ps1. Keep this file ASCII-only.
#
# Router mode: one llama-server process listens on the port from config\server.json and
# starts one child process per model on demand. Which models exist is written to a preset
# file (INI) that is generated from config\models.json on every start.

function Write-ModelPresetFile {
    # Translates config\models.json into the INI format of "llama-server --models-preset".
    # Returns the path of the generated file.
    $server = Get-ServerConfig
    New-Item -ItemType Directory -Force -Path $server.runDir | Out-Null
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('; Generated by scripts\lib\Server.ps1 from config\models.json and config\machine.json. Do not edit.')
    $lines.Add('version = 1')
    # the cards chosen with /gpu ("devices" in config\server.json); only with a choice are the
    # cards asked for, so that an id no card has any more cannot stop a model from loading
    $chosen = @()
    if (@(Get-DeviceChoice).Count -gt 0) {
        $chosen = @((Resolve-DeviceChoice (Get-UsableDevices (Get-LlamaDevices $server.exe)) @(Get-DeviceChoice)).devices | ForEach-Object { [string]$_.id })
    }
    foreach ($name in (Get-ModelNames)) {
        $model = Get-ModelProfile $name
        # a profile whose model is not downloaded on this machine is simply left out
        # (scripts\Get-Model.ps1 fetches it)
        if (-not (Test-Path $model.path)) { continue }
        # a plan for other cards gives way to the choice; noted here instead of a warning at
        # every start (models of other roles keep such plans until they are planned again)
        $dropped = Limit-ModelDevices $model.args $chosen
        $lines.Add('')
        if ($dropped) { $lines.Add("; planned for other cards than the chosen ones, llama.cpp places it by itself (scripts\Plan-Models.ps1 -Model $name plans it again)") }
        $lines.Add("[$name]")
        $lines.Add("model = $($model.path)")
        # Without its image encoder a model still loads, it just cannot read images.
        $noVision = $model.args.Contains('mmproj') -and -not (Test-Path $model.args['mmproj'])
        if ($noVision) { Write-Warning "Model '$name': image encoder $($model.args['mmproj']) is missing, loading without image input. See docs\models.md." }
        foreach ($key in $model.args.Keys) {
            if ($noVision -and $key -like 'mmproj*') { continue }
            $value = $model.args[$key]
            if ($value -is [bool]) { $value = $value.ToString().ToLower() }
            # numbers must use a dot, whatever the Windows region is
            if ($value -is [double] -or $value -is [decimal]) { $value = $value.ToString([Globalization.CultureInfo]::InvariantCulture) }
            $lines.Add("$key = $value")
        }
    }
    $file = Join-Path $server.runDir 'models.ini'
    [System.IO.File]::WriteAllLines($file, $lines, (New-Object System.Text.UTF8Encoding($false)))
    return $file
}

function Get-ServerApiKey {
    # The key every client has to send ("requireApiKey" in config\server.json), or '' if the
    # server runs without one. Created on first use: 32 random bytes as hex.
    # Why a key on a server that only listens on this machine: without it every web page
    # open in a browser could talk to it.
    $server = Get-ServerConfig
    if (-not $server.requireApiKey) { return '' }
    if (-not (Test-Path $server.apiKeyFile)) {
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $server.apiKeyFile) | Out-Null
        $bytes = New-Object byte[] 32
        $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
        try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
        [System.IO.File]::WriteAllText($server.apiKeyFile, (-join ($bytes | ForEach-Object { $_.ToString('x2') })))
    }
    return ([System.IO.File]::ReadAllText($server.apiKeyFile)).Trim()
}

function Test-ServerUp {
    try {
        $null = Invoke-RestMethod -Uri "$((Get-ServerConfig).baseUrl)/health" -TimeoutSec 3
        return $true
    } catch { return $false }
}

function Get-ServerProcess {
    # Only processes from our install folder: Ollama ships its own llama-server.exe.
    $root = (Get-ServerConfig).installRoot
    return @(Get-Process -Name 'llama-server' -ErrorAction SilentlyContinue | Where-Object { $_.Path -and $_.Path.StartsWith($root, [StringComparison]::OrdinalIgnoreCase) })
}

function Start-Server {
    # Starts the router if it is not running yet. Idempotent.
    if (Test-ServerUp) { return }
    $server = Get-ServerConfig
    if (-not (Test-Path $server.exe)) { throw "llama-server not found at $($server.exe). Run scripts\Install-LlamaCpp.ps1 first." }
    $preset = Write-ModelPresetFile
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $server.logFile) | Out-Null

    # llama-server also reads its options from LLAMA_ARG_* variables. Leftovers (for example
    # LLAMA_ARG_TENSOR_SPLIT from the Ollama setup) would silently change every model.
    Get-ChildItem Env: | Where-Object { $_.Name -like 'LLAMA_ARG_*' } | ForEach-Object { Remove-Item "Env:$($_.Name)" }

    # The key goes through the environment, not the command line: the router hands its
    # environment to the model processes, so they ask for the same key on their own ports,
    # and the key does not show up in process lists.
    $key = Get-ServerApiKey
    if ($key) { $env:LLAMA_API_KEY = $key }

    $argList = @(
        '--host', $server.host,
        '--port', $server.port,
        '--models-preset', "`"$preset`"",
        '--models-max', $server.modelsMax,
        '--models-memory-margin', $server.memoryMarginMiB,
        '--no-ui',
        '--offline',
        '--log-file', "`"$($server.logFile)`""
    )
    # which web pages may read answers of the server from a browser
    if ($server.corsOrigins) { $argList += @('--cors-origins', [string]$server.corsOrigins) }
    try {
        Start-Process -FilePath $server.exe -ArgumentList $argList -WorkingDirectory $server.binDir -WindowStyle Hidden
    } finally {
        Remove-Item Env:LLAMA_API_KEY -ErrorAction SilentlyContinue
    }

    $deadline = (Get-Date).AddSeconds([int]$server.startTimeoutSeconds)
    while ((Get-Date) -lt $deadline) {
        if (Test-ServerUp) { return }
        Start-Sleep -Milliseconds 500
    }
    throw "llama-server did not come up within $($server.startTimeoutSeconds) seconds. Log: $($server.logFile)"
}

function Stop-Server {
    foreach ($p in (Get-ServerProcess)) {
        try { Stop-Process -Id $p.Id -Force -Confirm:$false -ErrorAction Stop } catch {}
    }
    for ($i = 0; $i -lt 20; $i++) {
        if (-not (Get-ServerProcess)) { return }
        Start-Sleep -Milliseconds 250
    }
}

function Invoke-ServerApi {
    # Calls the server. With -Body it sends a POST with JSON, otherwise a GET.
    param([string]$Path, $Body = $null, [int]$TimeoutSec = 900)
    $uri = "$((Get-ServerConfig).baseUrl)$Path"
    $headers = @{}
    $key = Get-ServerApiKey
    if ($key) { $headers['Authorization'] = "Bearer $key" }
    if ($null -eq $Body) { return Invoke-RestMethod -Uri $uri -Headers $headers -TimeoutSec $TimeoutSec }
    $bytes = [System.Text.Encoding]::UTF8.GetBytes(($Body | ConvertTo-Json -Depth 20))
    return Invoke-RestMethod -Uri $uri -Method Post -Body $bytes -ContentType 'application/json' -Headers $headers -TimeoutSec $TimeoutSec
}

function Get-ServerModels {
    # All profiles the router knows, with their state: unloaded, loading, loaded, ...
    return @((Invoke-ServerApi '/models').data | ForEach-Object {
            [pscustomobject]@{ name = $_.id; status = [string]$_.status.value }
        })
}

function Wait-ModelLoaded([string]$Name) {
    # Asks the router to load a model and waits until it is ready. Returns the seconds it took.
    $timeout = [int](Get-ServerConfig).loadTimeoutSeconds
    $watch = [Diagnostics.Stopwatch]::StartNew()
    $state = (Get-ServerModels | Where-Object { $_.name -eq $Name }).status
    if (-not $state) { throw "The server does not know the model '$Name'. Check config\models.json and restart the server." }
    if ($state -eq 'sleeping') {
        # asleep after sleep-idle-seconds: the router counts it as running and refuses to load
        # it ("model is already running", 400), and its GPU memory is free; load it afresh
        Stop-Models @($Name)
        $state = 'unloaded'
    }
    if ($state -ne 'loaded' -and $state -ne 'loading') { $null = Invoke-ServerApi '/models/load' @{ model = $Name } 60 }
    while ($watch.Elapsed.TotalSeconds -lt $timeout) {
        $state = (Get-ServerModels | Where-Object { $_.name -eq $Name }).status
        if ($state -eq 'loaded') { return [math]::Round($watch.Elapsed.TotalSeconds, 1) }
        Start-Sleep -Milliseconds 500
    }
    throw "Model '$Name' was not loaded within $timeout seconds (state: $state). Log: $((Get-ServerConfig).logFile)"
}

function Stop-Models([string[]]$Names) {
    # Unloads the named models and waits until their GPU memory is free; the router itself
    # keeps running. Models that are not loaded are skipped; a sleeping one still has its
    # process and main memory, so it is unloaded as well.
    foreach ($m in (Get-ServerModels)) {
        if ($Names -contains $m.name -and ($m.status -eq 'loaded' -or $m.status -eq 'loading' -or $m.status -eq 'sleeping')) {
            try { $null = Invoke-ServerApi '/models/unload' @{ model = $m.name } 60 } catch {}
        }
    }
    for ($i = 0; $i -lt 60; $i++) {
        if (-not (Get-ServerModels | Where-Object { $Names -contains $_.name -and $_.status -ne 'unloaded' })) { return }
        Start-Sleep -Milliseconds 500
    }
}

function Stop-AllModels {
    # Unloads every model; the router itself keeps running.
    Stop-Models (Get-ModelNames)
}
